<?php
require '../PRACTICAL-8/db.php'; $db=db();$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'';
if($action==='delete'){ $id=(int)$_POST['id'];$s=$db->prepare('SELECT poster FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();if($row&&$row['poster']&&is_file(__DIR__.'/uploads/'.$row['poster']))unlink(__DIR__.'/uploads/'.$row['poster']);$s=$db->prepare('DELETE FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$message='Event deleted.';}
else if($action==='save'){ $title=trim($_POST['title']);$date=$_POST['event_date'];$category=trim($_POST['category']);$poster='';
if(!empty($_FILES['poster']['name'])){ $file=$_FILES['poster'];$allowed=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'];$size=@getimagesize($file['tmp_name']);$mime=$size?$size['mime']:'';if($file['error']!==UPLOAD_ERR_OK||$file['size']>2097152||!isset($allowed[$mime])){$message='Upload a JPG, PNG or WebP image smaller than 2 MB.';}else{$poster=bin2hex(random_bytes(8)).$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],__DIR__.'/uploads/'.$poster)){ $message='Upload failed.';$poster=''; }}}
if(!$message){$id=(int)($_POST['id']??0);if($id){if($poster){$s=$db->prepare('UPDATE events SET title=?,event_date=?,category=?,poster=? WHERE id=?');$s->bind_param('ssssi',$title,$date,$category,$poster,$id);}else{$s=$db->prepare('UPDATE events SET title=?,event_date=?,category=? WHERE id=?');$s->bind_param('sssi',$title,$date,$category,$id);}}else{$s=$db->prepare('INSERT INTO events(title,event_date,category,poster) VALUES(?,?,?,?)');$s->bind_param('ssss',$title,$date,$category,$poster);}if($s->execute())$message='Event saved.';}}
}
$rows=$db->query('SELECT * FROM events ORDER BY event_date DESC')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../PRACTICAL-7/style.css"><title>Event Management</title></head><body><main class="box"><h1>Event Management</h1><?php if($message):?><div class="success"><?=htmlspecialchars($message)?></div><?php endif?><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="eventId"><label>Title<input name="title" id="eventTitle" required></label><label>Date<input type="date" name="event_date" id="eventDate" required></label><label>Category<input name="category" id="eventCategory"></label><label>Poster<input type="file" name="poster" accept="image/jpeg,image/png,image/webp"></label><button>Save Event</button></form><table><tr><th>Event</th><th>Date</th><th>Category</th><th>Poster</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['title'])?></td><td><?=htmlspecialchars($r['event_date'])?></td><td><?=htmlspecialchars($r['category'])?></td><td><?= $r['poster']?'Poster uploaded':'-' ?></td><td><button onclick='editEvent(<?=htmlspecialchars(json_encode($r),ENT_QUOTES)?>)'>Edit</button><form method="post" onsubmit="return confirm('Delete event?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach?></table></main><script>function editEvent(r){eventId.value=r.id;eventTitle.value=r.title;eventDate.value=r.event_date;eventCategory.value=r.category}</script></body></html>
